-- ---------------------------------------------------------------------------------------------
-- Log tables (section 3, D-060)
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION forbid_log_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'append_only_table %: % is not allowed', TG_TABLE_NAME, TG_OP USING ERRCODE = '42501';
END $$;

-- Status logs: UPDATE may change only the columns passed as trigger arguments; DELETE is refused
-- except for the cleanup jobs on otp_codes and upload_sessions (css.cleanup = on).
CREATE FUNCTION guard_status_log() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME IN ('otp_codes', 'upload_sessions') AND current_setting('css.cleanup', true) = 'on' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION 'append_only_table %: DELETE is not allowed', TG_TABLE_NAME USING ERRCODE = '42501';
  END IF;
  IF (to_jsonb(NEW) - TG_ARGV) IS DISTINCT FROM (to_jsonb(OLD) - TG_ARGV) THEN
    RAISE EXCEPTION 'append_only_table %: only % may change', TG_TABLE_NAME, array_to_string(TG_ARGV, ', ') USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON "audit_log" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER budget_ledger_append_only BEFORE UPDATE OR DELETE ON "budget_ledger" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER stock_movements_append_only BEFORE UPDATE OR DELETE ON "stock_movements" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER document_events_append_only BEFORE UPDATE OR DELETE ON "document_events" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER application_transfers_append_only BEFORE UPDATE OR DELETE ON "application_transfers" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER volunteer_categories_log_append_only BEFORE UPDATE OR DELETE ON "volunteer_categories_log" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER workflow_transitions_append_only BEFORE UPDATE OR DELETE ON "workflow_transitions" FOR EACH ROW EXECUTE FUNCTION forbid_log_change();
-- TRUNCATE bypasses row triggers; refuse it on the strict logs as well.
CREATE TRIGGER audit_log_no_truncate BEFORE TRUNCATE ON "audit_log" FOR EACH STATEMENT EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER budget_ledger_no_truncate BEFORE TRUNCATE ON "budget_ledger" FOR EACH STATEMENT EXECUTE FUNCTION forbid_log_change();
CREATE TRIGGER stock_movements_no_truncate BEFORE TRUNCATE ON "stock_movements" FOR EACH STATEMENT EXECUTE FUNCTION forbid_log_change();

