  EXECUTE FUNCTION guard_status_log('refresh_token_hash', 'previous_token_hash', 'last_seen_at', 'last_ip', 'revoked_at', 'revoked_by', 'revoke_reason');
CREATE TRIGGER otp_codes_status_log BEFORE UPDATE OR DELETE ON "otp_codes" FOR EACH ROW
  EXECUTE FUNCTION guard_status_log('attempts', 'consumed_at');
