  EXECUTE FUNCTION guard_status_log('revoked_at');
CREATE TRIGGER field_changes_status_log BEFORE UPDATE OR DELETE ON "field_changes" FOR EACH ROW
  EXECUTE FUNCTION guard_status_log('unlock_state', 'new_value', 'approved_by');

-- ---------------------------------------------------------------------------------------------
-- BD-03: beneficiary mobile must not be the submitting volunteer's mobile (section 18, BR-008)
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION check_beneficiary_mobile_not_volunteer(p_application_id uuid) RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM applications a
    JOIN beneficiaries b ON b.id = a.beneficiary_id
    LEFT JOIN volunteers v ON v.id = a.owner_volunteer_id
    LEFT JOIN users owner_user ON owner_user.id = v.user_id
    LEFT JOIN users creator ON creator.id = a.created_by_user_id
    WHERE a.id = p_application_id
      AND a.status <> 'deleted'
      AND (b.mobile = owner_user.mobile OR b.mobile = creator.mobile)
  ) THEN
    RAISE EXCEPTION 'beneficiary_mobile_is_volunteer_mobile' USING ERRCODE = '23514', HINT = 'BD-03';
  END IF;
END $$;

CREATE FUNCTION bd03_on_application() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  PERFORM check_beneficiary_mobile_not_volunteer(NEW.id);
  RETURN NULL;
END $$;

CREATE FUNCTION bd03_on_beneficiary() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE app record;
BEGIN
  FOR app IN SELECT id FROM applications WHERE beneficiary_id = NEW.id AND status <> 'deleted' LOOP
    PERFORM check_beneficiary_mobile_not_volunteer(app.id);
  END LOOP;
  RETURN NULL;
END $$;

CREATE FUNCTION bd03_on_user() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE app record;
BEGIN
  FOR app IN
    SELECT a.id FROM applications a
    WHERE a.status <> 'deleted'
      AND (a.created_by_user_id = NEW.id OR a.owner_volunteer_id IN (SELECT id FROM volunteers WHERE user_id = NEW.id))
  LOOP
    PERFORM check_beneficiary_mobile_not_volunteer(app.id);
  END LOOP;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER applications_bd03 AFTER INSERT OR UPDATE OF beneficiary_id, owner_volunteer_id, created_by_user_id, status
  ON "applications" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (NEW.status <> 'deleted') EXECUTE FUNCTION bd03_on_application();
CREATE CONSTRAINT TRIGGER beneficiaries_bd03 AFTER UPDATE OF mobile
  ON "beneficiaries" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION bd03_on_beneficiary();
CREATE CONSTRAINT TRIGGER users_bd03 AFTER UPDATE OF mobile
  ON "users" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION bd03_on_user();

-- ---------------------------------------------------------------------------------------------
-- Published form versions are immutable (BR-077, section 9)
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION forbid_published_form_change() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  rec record := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  v_version uuid;
  v_status text;
BEGIN
  IF TG_TABLE_NAME = 'field_options' THEN
    SELECT f.form_version_id INTO v_version FROM form_fields f WHERE f.id = rec.form_field_id;
  ELSE
    v_version := rec.form_version_id;
  END IF;
  SELECT status INTO v_status FROM form_versions WHERE id = v_version;
  IF v_status IS DISTINCT FROM 'draft' THEN
    RAISE EXCEPTION 'form_version_not_draft: % of a % form version cannot change', TG_TABLE_NAME, coalesce(v_status, 'missing') USING ERRCODE = '23514';
  END IF;
  RETURN rec;
END $$;
CREATE TRIGGER form_sections_immutable BEFORE INSERT OR UPDATE OR DELETE ON "form_sections" FOR EACH ROW EXECUTE FUNCTION forbid_published_form_change();
CREATE TRIGGER form_fields_immutable BEFORE INSERT OR UPDATE OR DELETE ON "form_fields" FOR EACH ROW EXECUTE FUNCTION forbid_published_form_change();
CREATE TRIGGER field_options_immutable BEFORE INSERT OR UPDATE OR DELETE ON "field_options" FOR EACH ROW EXECUTE FUNCTION forbid_published_form_change();

-- ---------------------------------------------------------------------------------------------
-- Verified vouchers are locked (BR-122)
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION forbid_locked_voucher_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.locked_at IS NOT NULL THEN
    RAISE EXCEPTION 'voucher_locked' USING ERRCODE = '23514';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE TRIGGER vouchers_locked BEFORE UPDATE OR DELETE ON "vouchers" FOR EACH ROW EXECUTE FUNCTION forbid_locked_voucher_change();

-- ---------------------------------------------------------------------------------------------
-- Qurbani: one animal, one volunteer; shares never exceed the animal (BR-145, section 14)
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION forbid_animal_reassignment() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD.assigned_volunteer_id IS NOT NULL AND NEW.assigned_volunteer_id IS NOT NULL
     AND NEW.assigned_volunteer_id <> OLD.assigned_volunteer_id THEN
    RAISE EXCEPTION 'animal_already_allocated: cancel the allocation first' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER animals_no_reassignment BEFORE UPDATE OF assigned_volunteer_id ON "animals" FOR EACH ROW EXECUTE FUNCTION forbid_animal_reassignment();

CREATE FUNCTION sync_animal_shares() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_animal uuid := CASE WHEN TG_OP = 'DELETE' THEN OLD.animal_id ELSE NEW.animal_id END;
  v_total smallint;
  v_sum integer;
BEGIN
  SELECT total_shares INTO v_total FROM animals WHERE id = v_animal FOR UPDATE;
  SELECT coalesce(sum(shares), 0) INTO v_sum FROM animal_shares WHERE animal_id = v_animal;
  IF v_sum > v_total THEN
    RAISE EXCEPTION 'animal_shares_exceeded: % of % shares', v_sum, v_total USING ERRCODE = '23514';
  END IF;
  UPDATE animals SET status = CASE WHEN v_sum = v_total THEN 'full' ELSE 'empty' END
  WHERE id = v_animal AND status <> 'allocated'
    AND status IS DISTINCT FROM CASE WHEN v_sum = v_total THEN 'full' ELSE 'empty' END;
  RETURN NULL;
END $$;
CREATE TRIGGER animal_shares_sync AFTER INSERT OR UPDATE OR DELETE ON "animal_shares" FOR EACH ROW EXECUTE FUNCTION sync_animal_shares();

-- ---------------------------------------------------------------------------------------------
-- Blocklist (BD-06, section 11): the subject must exist; mirror flags are kept in sync
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION check_blocklist_subject() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.subject_type = 'volunteer' AND NOT EXISTS (SELECT 1 FROM volunteers WHERE id = NEW.subject_id) THEN
    RAISE EXCEPTION 'blocklist_subject_missing: volunteer %', NEW.subject_id USING ERRCODE = '23503';
  END IF;
  IF NEW.subject_type = 'beneficiary' AND NOT EXISTS (SELECT 1 FROM beneficiaries WHERE id = NEW.subject_id) THEN
    RAISE EXCEPTION 'blocklist_subject_missing: beneficiary %', NEW.subject_id USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER blocklist_subject BEFORE INSERT OR UPDATE OF subject_type, subject_id ON "blocklist" FOR EACH ROW EXECUTE FUNCTION check_blocklist_subject();

CREATE FUNCTION sync_blocklist_flags() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_blocked boolean;
BEGIN
  SELECT EXISTS (SELECT 1 FROM blocklist WHERE subject_type = NEW.subject_type AND subject_id = NEW.subject_id AND active) INTO v_blocked;
  IF NEW.subject_type = 'beneficiary' THEN
    UPDATE beneficiaries SET is_blocked = v_blocked WHERE id = NEW.subject_id AND is_blocked IS DISTINCT FROM v_blocked;
  ELSE
    UPDATE users u SET state = CASE WHEN v_blocked THEN 'blocked' ELSE 'active' END, permission_version = u.permission_version + 1
    FROM volunteers v
    WHERE v.id = NEW.subject_id AND u.id = v.user_id
      AND ((v_blocked AND u.state = 'active') OR (NOT v_blocked AND u.state = 'blocked'));
  END IF;
  RETURN NULL;
END $$;
CREATE TRIGGER blocklist_sync AFTER INSERT OR UPDATE ON "blocklist" FOR EACH ROW EXECUTE FUNCTION sync_blocklist_flags();

-- ---------------------------------------------------------------------------------------------
-- media_consents.channels must be codes of the reference list consent_channel (section 5.2)
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION check_consent_channels() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_missing text;
BEGIN
  SELECT string_agg(c, ', ') INTO v_missing
  FROM unnest(NEW.channels) AS c
  WHERE NOT EXISTS (SELECT 1 FROM reference_lists r WHERE r.list_key = 'consent_channel' AND r.code = c);
  IF v_missing IS NOT NULL THEN
    RAISE EXCEPTION 'unknown_consent_channel: %', v_missing USING ERRCODE = '23503';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER media_consents_channels BEFORE INSERT OR UPDATE OF channels ON "media_consents" FOR EACH ROW EXECUTE FUNCTION check_consent_channels();

-- ---------------------------------------------------------------------------------------------
-- The Main Admin cannot disappear (AUTH.md section 11): at most one owner (partial unique index),
-- and an existing owner flag cannot be removed unless another owner exists
-- ---------------------------------------------------------------------------------------------
CREATE FUNCTION keep_system_owner() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM users WHERE is_system_owner) THEN
    RAISE EXCEPTION 'system_owner_required' USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER users_keep_system_owner AFTER UPDATE OF is_system_owner ON "users"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN (OLD.is_system_owner AND NOT NEW.is_system_owner)
  EXECUTE FUNCTION keep_system_owner();

-- ---------------------------------------------------------------------------------------------
-- Views (sections 13): stock reconciliation (BD-22) and project budget summary (BR-132)
-- ---------------------------------------------------------------------------------------------
CREATE VIEW stock_balances AS
SELECT project_id, volunteer_id, item, sent, received, distributed, remaining, damaged, returned,
       (sent = distributed + remaining + damaged) AS balanced
FROM (
  SELECT project_id, volunteer_id, item,
    coalesce(sum(quantity) FILTER (WHERE kind = 'sent'), 0) AS sent,
    coalesce(sum(quantity) FILTER (WHERE kind = 'received'), 0) AS received,
    coalesce(sum(quantity) FILTER (WHERE kind = 'distributed'), 0) AS distributed,
    coalesce(sum(quantity) FILTER (WHERE kind = 'remaining'), 0) AS remaining,
    coalesce(sum(quantity) FILTER (WHERE kind = 'damaged'), 0) AS damaged,
    coalesce(sum(quantity) FILTER (WHERE kind = 'returned'), 0) AS returned
  FROM stock_movements
  GROUP BY project_id, volunteer_id, item
) totals;

CREATE VIEW project_budget_summary AS
SELECT project_id, allocated, approved, spent, beneficiary_support, advance, actual_expense,
       voucher_submitted, voucher_verified, returned, expense_claimed, expense_paid,
       allocated - spent AS remaining,
       allocated - approved AS remaining_after_approved
FROM (
  SELECT project_id,
    coalesce(sum(amount) FILTER (WHERE bucket = 'allocated'), 0) AS allocated,
    coalesce(sum(amount) FILTER (WHERE bucket = 'approved'), 0) AS approved,
    coalesce(sum(amount) FILTER (WHERE bucket = 'spent'), 0) AS spent,
    coalesce(sum(amount) FILTER (WHERE bucket = 'beneficiary_support'), 0) AS beneficiary_support,
    coalesce(sum(amount) FILTER (WHERE bucket = 'advance'), 0) AS advance,
    coalesce(sum(amount) FILTER (WHERE bucket = 'actual_expense'), 0) AS actual_expense,
    coalesce(sum(amount) FILTER (WHERE bucket = 'voucher_submitted'), 0) AS voucher_submitted,
    coalesce(sum(amount) FILTER (WHERE bucket = 'voucher_verified'), 0) AS voucher_verified,
    coalesce(sum(amount) FILTER (WHERE bucket = 'returned'), 0) AS returned,
    coalesce(sum(amount) FILTER (WHERE bucket = 'expense_claimed'), 0) AS expense_claimed,
    coalesce(sum(amount) FILTER (WHERE bucket = 'expense_paid'), 0) AS expense_paid
  FROM budget_ledger
  GROUP BY project_id
) buckets;
